import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.ArrayDeque;
import java.util.Queue;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') {
                ptr++;
            }
            return hasNextByte();
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = readByte();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sgn;
        }
    }

    static class Edge implements Comparable<Edge> {
        int u, v, w;

        Edge(int u, int v, int w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }

        @Override
        public int compareTo(Edge o) {
            return Integer.compare(o.w, this.w); // Ordem decrescente
        }
    }

    static class DSU {
        int[] parent;

        DSU(int n) {
            parent = new int[n + 1];
            for (int i = 1; i <= n; i++) parent[i] = i;
        }

        int find(int i) {
            if (parent[i] == i)
                return i;
            return parent[i] = find(parent[i]);
        }

        boolean union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                parent[rootI] = rootJ;
                return true;
            }
            return false;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        if (!sc.hasNext()) return;

        int n = sc.nextInt();
        int b = sc.nextInt();

        Edge[] edges = new Edge[b];
        for (int i = 0; i < b; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int w = sc.nextInt();
            edges[i] = new Edge(u, v, w);
        }

        Arrays.sort(edges);

        // Representação da árvore geradora máxima via Forward Star
        int[] head = new int[n + 1];
        Arrays.fill(head, -1);
        int[] to = new int[2 * (n - 1)];
        int[] weight = new int[2 * (n - 1)];
        int[] next = new int[2 * (n - 1)];
        int edgeCount = 0;

        DSU dsu = new DSU(n);
        int edgesAdded = 0;
        for (int i = 0; i < b; i++) {
            Edge e = edges[i];
            if (dsu.union(e.u, e.v)) {
                // Adiciona e.u -> e.v
                to[edgeCount] = e.v;
                weight[edgeCount] = e.w;
                next[edgeCount] = head[e.u];
                head[e.u] = edgeCount++;

                // Adiciona e.v -> e.u
                to[edgeCount] = e.u;
                weight[edgeCount] = e.w;
                next[edgeCount] = head[e.v];
                head[e.v] = edgeCount++;

                edgesAdded++;
                if (edgesAdded == n - 1) break;
            }
        }

        // Preprocessamento de LCA com Binary Lifting
        int LOGN = 18;
        int[][] up = new int[LOGN][n + 1];
        int[][] minEdge = new int[LOGN][n + 1];
        int[] depth = new int[n + 1];
        boolean[] visited = new boolean[n + 1];

        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(1);
        visited[1] = true;
        depth[1] = 0;
        up[0][1] = 1;
        minEdge[0][1] = Integer.MAX_VALUE;

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                int w = weight[e];
                if (!visited[v]) {
                    visited[v] = true;
                    depth[v] = depth[u] + 1;
                    up[0][v] = u;
                    minEdge[0][v] = w;
                    queue.add(v);
                }
            }
        }

        for (int k = 1; k < LOGN; k++) {
            for (int i = 1; i <= n; i++) {
                int mid = up[k - 1][i];
                up[k][i] = up[k - 1][mid];
                minEdge[k][i] = Math.min(minEdge[k - 1][i], minEdge[k - 1][mid]);
            }
        }

        int c = sc.nextInt();
        PrintWriter out = new PrintWriter(System.out);

        for (int q = 0; q < c; q++) {
            int u = sc.nextInt();
            int v = sc.nextInt();

            if (depth[u] < depth[v]) {
                int temp = u;
                u = v;
                v = temp;
            }

            int ans = Integer.MAX_VALUE;

            // Iguala as profundidades
            for (int k = LOGN - 1; k >= 0; k--) {
                if (depth[u] - (1 << k) >= depth[v]) {
                    ans = Math.min(ans, minEdge[k][u]);
                    u = up[k][u];
                }
            }

            if (u == v) {
                out.println(ans);
                continue;
            }

            // Sobe simultaneamente até o LCA
            for (int k = LOGN - 1; k >= 0; k--) {
                if (up[k][u] != up[k][v]) {
                    ans = Math.min(ans, minEdge[k][u]);
                    ans = Math.min(ans, minEdge[k][v]);
                    u = up[k][u];
                    v = up[k][v];
                }
            }

            ans = Math.min(ans, minEdge[0][u]);
            ans = Math.min(ans, minEdge[0][v]);

            out.println(ans);
        }

        out.flush();
    }
}
